function medianeDeuxTries(a, b) {
    if (a.length > b.length) [a, b] = [b, a];
    const m = a.length;
    const n = b.length;
    let low = 0, high = m;

    while (low <= high) {
        const partA = Math.floor((low + high) / 2);
        const partB = (m + n) % 2 === 0 ? partA : partA - 1;

        const a1 = partA === 0 ? Number.MIN_SAFE_INTEGER : a[partA - 1];
        const a2 = partA === m ? Number.MAX_SAFE_INTEGER : a[partA];
        const b1 = partB === 0 ? Number.MIN_SAFE_INTEGER : b[partB - 1];
        const b2 = partB === n ? Number.MAX_SAFE_INTEGER : b[partB];

        if (a2 <= b1 && b2 <= a1) {
            return ((m + n) % 2 === 0 
                ? (Math.max(a1, b1) + Math.min(a2, b2)) / 2 
                : Math.max(a1, b1));
